427: async function writeAtomic(
428:   filePath: string,
429:   body: string,
430:   fs: AtomicFileSystem = defaultAtomicFileSystem,
431: ): Promise<void> {
432:   let tmp: string | undefined;
433:   try {
434:     tmp = await stageAtomic(filePath, body, fs);
435:     await commitAtomic(tmp, filePath, fs);
436:   } catch (error) {
437:     if (tmp) await removeAtomicTemp(tmp, fs);
438:     throw error;
439:   }
