442: async function stageAtomic(filePath: string, body: string, fs: AtomicFileSystem): Promise<string> {
443:   const tmp = `${filePath}.${process.pid}.${randomBytes(6).toString('hex')}.tmp`;
444:   const handle = await fs.open(tmp, 'w', 0o600);
445:   try {
446:     await closeAfter(handle, async () => {
447:       await handle.writeFile(body);
448:       await handle.sync();
449:     });
450:   } catch (error) {
451:     await removeAtomicTemp(tmp, fs);
452:     throw error;
453:   }
454:   return tmp;
455: }
456: 
457: async function commitAtomic(tmp: string, filePath: string, fs: AtomicFileSystem): Promise<void> {
458:   await fs.rename(tmp, filePath);
459:   const directory = await fs.open(path.dirname(filePath), 'r');
460:   await closeAfter(directory, () => directory.sync());
461: }
