483: // Cleanup is best-effort so a secondary rm failure never hides the causal storage error.
484: async function removeAtomicTemp(tmp: string, fs: AtomicFileSystem): Promise<void> {
485:   try {
486:     await fs.rm(tmp, { force: true });
487:   } catch {
488:     // The original write, sync, close, or rename error is more useful to the caller.
489:   }
490: }
