496: function encodeBase32(value: bigint, chars: number): string {
497:   let out = '';
498:   for (let shift = (chars - 1) * 5; shift >= 0; shift -= 5) {
499:     out += ALPHABET[Number((value >> BigInt(shift)) & 31n)];
500:   }
501:   return out;
502: }
