504: function exclusive<T>(root: string, fn: () => Promise<T>): Promise<T> {
505:   const key = path.resolve(root);
506:   const previous = tails.get(key) ?? Promise.resolve();
507:   const run = previous.then(fn, fn);
508:   tails.set(key, run.then(() => undefined, () => undefined));
509:   return run;
510: }
