1: // What: exposes local report building, progress, and cancellation over IPC.
2: // Why: the engine and stored session files stay in main; the renderer receives only validated results.
3: // Removed: the Report screen could not request a real report, see progress, or stop one.
4: import { ipcMain } from 'electron';
5: import {
6:   reportBuildRequestSchema,
7:   reportCancelRequestSchema,
8:   reportCancelResultSchema,
9:   reportProgressSchema,
10:   reportResultSchema,
11: } from '../shared/contracts.js';
12: import { buildReport } from './report.js';
13: import { withReportExclusion } from './report-lock.js';
14: import { defaultDataRoot } from './store.js';
15: 
16: export const REPORT_BUILD_CHANNEL = 'cp:report:build';
17: export const REPORT_PROGRESS_CHANNEL = 'cp:report:progress';
18: export const REPORT_CANCEL_CHANNEL = 'cp:report:cancel';
19: 
20: interface ActiveBuild {
21:   controller: AbortController;
22:   /** Once true, the artifact commit has begun and a cancel request must not be acknowledged. */
23:   committing: boolean;
24: }
25: 
26: /** One active build per session. */
27: const activeBuilds = new Map<string, ActiveBuild>();
28: 
29: export function registerReportHandler(dataRoot: () => string = defaultDataRoot): void {
30:   ipcMain.handle(REPORT_BUILD_CHANNEL, async (event, payload: unknown) => {
31:     const parsed = reportBuildRequestSchema.safeParse(payload);
32:     if (!parsed.success) {
33:       throw new Error('Choose a valid session and up to 20 PGNs under 2 MB.');
34:     }
35:     const { sessionId, pgns } = parsed.data;
36:     if (activeBuilds.has(sessionId)) {
37:       throw new Error('A report build is already running for this session.');
38:     }
39:     const build: ActiveBuild = { controller: new AbortController(), committing: false };
40:     activeBuilds.set(sessionId, build);
41:     try {
42:       // Shared exclusion also covers insight artifact reads; only one Stockfish build runs at once.
43:       const result = await withReportExclusion(() =>
44:         buildReport(dataRoot(), sessionId, pgns, undefined, {
45:           signal: build.controller.signal,
46:           onCommitStart: () => {
47:             build.committing = true;
48:           },
49:           onProgress: (progress) => {
50:             if (event.sender.isDestroyed()) return;
51:             const message = reportProgressSchema.safeParse({ sessionId, ...progress });
52:             if (message.success) event.sender.send(REPORT_PROGRESS_CHANNEL, message.data);
53:           },
54:         }),
55:       );
56:       return reportResultSchema.parse(result);
57:     } finally {
58:       if (activeBuilds.get(sessionId) === build) activeBuilds.delete(sessionId);
59:     }
60:   });
61: 
62:   ipcMain.handle(REPORT_CANCEL_CHANNEL, (_event, payload: unknown) => {
63:     const parsed = reportCancelRequestSchema.safeParse(payload);
64:     if (!parsed.success) {
65:       throw new Error('Choose a session to cancel.');
66:     }
67:     const build = activeBuilds.get(parsed.data.sessionId);
68:     if (!build) return reportCancelResultSchema.parse({ cancelled: false });
69:     // A commit already in progress is not cancellable; acknowledging it would lie about the artifact.
70:     if (build.committing) return reportCancelResultSchema.parse({ cancelled: false });
71:     build.controller.abort();
72:     return reportCancelResultSchema.parse({ cancelled: true });
73:   });
74: }

