17: export const INSIGHT_CANCEL_CHANNEL = 'cp:insight:cancel';
18: 
19: export function registerInsightHandler(dataRoot: () => string = defaultDataRoot, env: NodeJS.ProcessEnv = process.env): void {
20:   const active = new Map<string, AbortController>();
21: 
22:   ipcMain.handle(INSIGHT_REQUEST_CHANNEL, async (_event, payload: unknown) => {
23:     const parsed = insightRequestSchema.safeParse(payload);
24:     if (!parsed.success) throw new Error('Choose a session, provider, and question under 4 KB.');
25:     if (active.has(parsed.data.sessionId)) throw new Error('An AI reading is already running for this session.');
26:     const requestId = randomUUID();
27:     const controller = new AbortController();
28:     active.set(parsed.data.sessionId, controller);
