39:     } catch (error) {
40:       logError(`[chesspulse] AI reading ${requestId} failed`);
41:       throw error;
42:     } finally {
43:       if (active.get(parsed.data.sessionId) === controller) active.delete(parsed.data.sessionId);
44:     }
45:   });
46: 
