48:     const parsed = insightCancelRequestSchema.safeParse(payload);
49:     if (!parsed.success) throw new Error('Choose a session to cancel.');
50:     const controller = active.get(parsed.data.sessionId);
51:     controller?.abort();
52:     return { cancelled: controller !== undefined };
53:   });
54: }

