export async function startSession(
  root: string,
  anchor: SessionAnchor,
  timeControl: string,
  hooks: SessionHooks = {},
): Promise<SessionMeta> {
  const parsed = sessionStartRequestSchema.safeParse({ timeControl });
  if (!parsed.success) throw new Error('Choose a time control before starting.');
