  writable?: (dir: string) => Promise<boolean>;
  aiConfig?: AiConfigState;
}
```
Hmm `camera` as check or function is awkward. Use `cameraCheck?: () => DoctorCheck | Promise<DoctorCheck>`; default `defaultCameraCheck`.
`engineProbe` default `probeEngine`.
`writableProbe` default `probeWritable`.
`envFile` default load from `process.cwd()/.env`? For CLI pass; for tests pass.
`aiConfig` default `readAiConfig(env)`.

Engine probe:
```ts
const START_FEN = 'rnbqkbnr/pppppppp/8/8/8/8/PPPPPPPP/RNBQKBNR w KQkq - 0 1';
export async function probeEngine(): Promise<DoctorCheck> {
  const engine = createEngine({ depth: 1, timeoutMs: 5000, maxRestarts: 0 });
  try {
    const result = await engine.evaluate(START_FEN);
    if (result.evalFailed) return check('engine','Stockfish','fail', `No answer: ${result.reason ?? 'unknown'}.`);
    return check(...,'pass','Stockfish answered UCI and scored the start position.');
  } finally { await engine.close().catch(()=>undefined); }
}
