```ts
async function probeWritable(dir: string): Promise<boolean> {
  try { await mkdir(dir, {recursive:true, mode:0o700}); const file = path.join(dir, `.doctor-${process.pid}-${randomBytes(4).toString('hex')}`); await writeFile(file,'ok',{mode:0o600}); await unlink(file); return true; } catch { return false; }
}
