export function registerLibraryHandler(dataRoot = defaultDataRoot): void {
  registerInvokeChannel('sessionDelete', async (_event, payload) => {
    return sessionDeleteResultSchema.parse({ deleted: await deleteSession(dataRoot(), payload.sessionId) });
  });
  registerInvokeChannel('reportExport', async (_event, payload) => {
    let report;
    try { report = await readReport(dataRoot(), payload.sessionId); }
    catch (error) { throw reportError(error); }
    const choice = await dialog.showSaveDialog({
      title: 'Export report',
