    if (choice.canceled || !choice.filePath) return reportExportResultSchema.parse(exportResult(undefined));
    try { await writeReportExport(report, choice.filePath); }
    catch (error) { throw toAppError(error, 'storage_failed'); }
    return reportExportResultSchema.parse(exportResult(choice.filePath));
  });
}
