- none → `{found:false, path: first}`.

Add to env.ts:
```ts
export function loadEnvCandidates(files: readonly string[], env): EnvLoadResult {
  let first = files[0] ?? '';
  for (const file of files) {
    if (!file) continue;
    if (!first) first = file;
    const result = loadEnvFile(file, env);
    if (result.found) return result;
  }
  return { found: false, path: first };
}
```
Filter empty paths.

Index:
```ts
const envFiles = [
  process.env.CHESSPULSE_ENV_FILE ?? '',
  app.isPackaged
    ? path.join(path.dirname(process.env.APPIMAGE ?? app.getPath('exe')), '.env')
