const packagedLibrary = path.join(resources, 'smartspectra', 'libsmartspectra_capi.so');

if (!process.env.SMARTSPECTRA_CAPI_PATH && existsSync(packagedLibrary)) {
  process.env.SMARTSPECTRA_CAPI_PATH = packagedLibrary;
}

